  function calcQuizClient(selectedOptionsMap) {
    const scores = { pleyadianos: 0, andromedanos: 0, sirianos: 0, arcturianos: 0, liranos: 0, orionitas: 0 };
    for (const q of STATIC_QUESTIONS) {
      const chosenId = selectedOptionsMap[q.id];
      const opt = q.options.find(o => o.id === chosenId) || q.options[0];
      for (const [k, pts] of Object.entries(opt.weights)) {
        if (scores[k] !== undefined) scores[k] += pts;
      }
    }
    const total = Object.values(scores).reduce((a, b) => a + b, 0) || 1;
    const sorted = Object.entries(scores)
      .map(([key, rawScore]) => ({ key, rawScore, percentage: Math.round((rawScore / total) * 100) }))
      .sort((a, b) => (b.rawScore !== a.rawScore ? b.rawScore - a.rawScore : a.key.localeCompare(b.key)));
    const top1 = sorted[0];
    const top2 = sorted[1];
    const isMixed = (top1.rawScore - top2.rawScore) <= 2 && top2.rawScore >= 8;
    const primaryKey = isMixed ? 'mixta' : top1.key;
    const prof = STATIC_PROFILES[primaryKey];
    return {
      primary_resonance: primaryKey,
      dominant_lineage: top1.key,
      secondary_resonance: top2.key,
      is_mixed: isMixed,
      scores_breakdown: sorted,
      profile: {
        ...prof,
        illustration: prof.illustration.replace(/^\//, ''),
        dominant_name: STATIC_PROFILES[top1.key].title,
        secondary_name: STATIC_PROFILES[top2.key].title
      }
    };
  }

